package com.cpgame.glacier;

import java.math.BigDecimal;
import java.util.Properties;

/** Immutable Redis output limits. Zero is subject to the same inclusive range. */
public final class LoaderLimits {
    private final BigDecimal normalMin, normalMax, specialMin, specialMax;
    public final int specialCap;
    public LoaderLimits(Properties p) {
        normalMin = number(p, "0", "generation.normal-min-win-multiplier", "range.normal-min");
        specialMin = number(p, "0", "generation.special-min-win-multiplier", "generation.mary-min-win-multiplier", "range.special-min");
        normalMax = number(p, "999999999", "generation.normal-max-win-multiplier", "generation.normal-max-total-multiplier", "generation.normal-max-total-win-multiplier", "generation.normal-pool-max-win-multiplier", "range.normal-max");
        specialMax = number(p, "999999999", "generation.special-max-win-multiplier", "generation.mary-max-win-multiplier", "generation.special-max-total-multiplier", "generation.special-max-total-win-multiplier", "generation.special-pool-max-win-multiplier", "range.special-max");
        specialCap = number(p, "100", "generation.special-max-members-per-multiplier", "retention.special-per-multiplier").intValueExact();
        if (normalMin.signum()<0 || specialMin.signum()<0 || normalMax.compareTo(normalMin)<0 || specialMax.compareTo(specialMin)<0 || specialCap<1)
            throw new IllegalArgumentException("Invalid inclusive multiplier range or special bucket retention");
    }
    public boolean accepts(boolean special, int value) { return accepts(special, BigDecimal.valueOf(value)); }
    public boolean accepts(boolean special, BigDecimal value) {
        return value.compareTo(special ? specialMin : normalMin)>=0 && value.compareTo(special ? specialMax : normalMax)<=0;
    }
    public int lossTarget(int configured) { return accepts(false, 0) ? configured : 0; }
    public static long attemptLimit(long target) { return Math.max(100_000L, Math.multiplyExact(Math.max(1, target), 10_000L)); }
    public static void checkAttempts(long attempts, long target) {
        if (attempts > attemptLimit(target)) throw new IllegalStateException("Configured range, weights or round limits cannot satisfy the requested count; candidate limit reached");
    }
    public static void checkKeys(Properties p) {
        java.util.Set<String> allowed=new java.util.HashSet<String>(java.util.Arrays.asList("generation.batch-size","generation.cap.cascade-pages","generation.cap.scatter-symbols-column","generation.cap.scatter-symbols-free","generation.cap.scatter-units-board","generation.cap.scatter-units-reel","generation.cap.wild-board","generation.cap.wild-reel","generation.entry-switch-every","generation.loss-count","generation.loss.constructive-attempts","generation.loss.fallback-samples","generation.mary-max-win-multiplier","generation.mary-min-win-multiplier","generation.max-consecutive-wins","generation.max-mary-spins","generation.max-members-per-multiplier","generation.normal-max-total-multiplier","generation.normal-max-total-win-multiplier","generation.normal-max-win-multiplier","generation.normal-min-win-multiplier","generation.normal-pool-max-win-multiplier","generation.silver-to-gold.1-weight","generation.silver-to-gold.10-weight","generation.silver-to-gold.11-weight","generation.silver-to-gold.2-weight","generation.silver-to-gold.3-weight","generation.silver-to-gold.4-weight","generation.silver-to-gold.5-weight","generation.silver-to-gold.6-weight","generation.silver-to-gold.7-weight","generation.silver-to-gold.8-weight","generation.silver-to-gold.9-weight","generation.special-count","generation.special-max-members-per-multiplier","generation.special-max-total-multiplier","generation.special-max-total-win-multiplier","generation.special-max-win-multiplier","generation.special-min-win-multiplier","generation.special-pool-max-win-multiplier","generation.special-scatter-boost","generation.structure.paid-initial.1N-1N-1N-1N-1N","generation.structure.paid-initial.1N-1N-1N-2N","generation.structure.paid-initial.1N-1N-1N-2S","generation.structure.paid-initial.1N-1N-2N-1N","generation.structure.paid-initial.1N-1N-2S-1N","generation.structure.paid-initial.1N-1N-3N","generation.structure.paid-initial.1N-1N-3S","generation.structure.paid-initial.1N-2N-1N-1N","generation.structure.paid-initial.1N-2N-2N","generation.structure.paid-initial.1N-2N-2S","generation.structure.paid-initial.1N-2S-1N-1N","generation.structure.paid-initial.1N-2S-2N","generation.structure.paid-initial.1N-2S-2S","generation.structure.paid-initial.1N-3N-1N","generation.structure.paid-initial.1N-3S-1N","generation.structure.paid-initial.1N-4N","generation.structure.paid-initial.1N-4S","generation.structure.paid-initial.2N-1N-1N-1N","generation.structure.paid-initial.2N-1N-2N","generation.structure.paid-initial.2N-1N-2S","generation.structure.paid-initial.2N-2N-1N","generation.structure.paid-initial.2N-2S-1N","generation.structure.paid-initial.2N-3N","generation.structure.paid-initial.2N-3S","generation.structure.paid-initial.2S-1N-1N-1N","generation.structure.paid-initial.2S-1N-2N","generation.structure.paid-initial.2S-1N-2S","generation.structure.paid-initial.2S-2N-1N","generation.structure.paid-initial.2S-2S-1N","generation.structure.paid-initial.2S-3N","generation.structure.paid-initial.2S-3S","generation.structure.paid-initial.3N-1N-1N","generation.structure.paid-initial.3N-2N","generation.structure.paid-initial.3N-2S","generation.structure.paid-initial.3S-1N-1N","generation.structure.paid-initial.3S-2N","generation.structure.paid-initial.3S-2S","generation.structure.paid-initial.4N-1N","generation.structure.paid-initial.4S-1N","generation.symbol.1.free-initial-weight","generation.symbol.1.free-refill-weight","generation.symbol.1.paid-initial-weight","generation.symbol.1.paid-refill-weight","generation.symbol.10.free-initial-weight","generation.symbol.10.free-refill-weight","generation.symbol.10.paid-initial-weight","generation.symbol.10.paid-refill-weight","generation.symbol.11.free-initial-weight","generation.symbol.11.free-refill-weight","generation.symbol.11.paid-initial-weight","generation.symbol.11.paid-refill-weight","generation.symbol.12.free-initial-weight","generation.symbol.12.free-refill-weight","generation.symbol.12.paid-initial-weight","generation.symbol.12.paid-refill-weight","generation.symbol.13.free-initial-weight","generation.symbol.13.free-refill-weight","generation.symbol.13.paid-initial-weight","generation.symbol.13.paid-refill-weight","generation.symbol.2.free-initial-weight","generation.symbol.2.free-refill-weight","generation.symbol.2.paid-initial-weight","generation.symbol.2.paid-refill-weight","generation.symbol.3.free-initial-weight","generation.symbol.3.free-refill-weight","generation.symbol.3.paid-initial-weight","generation.symbol.3.paid-refill-weight","generation.symbol.4.free-initial-weight","generation.symbol.4.free-refill-weight","generation.symbol.4.paid-initial-weight","generation.symbol.4.paid-refill-weight","generation.symbol.5.free-initial-weight","generation.symbol.5.free-refill-weight","generation.symbol.5.paid-initial-weight","generation.symbol.5.paid-refill-weight","generation.symbol.6.free-initial-weight","generation.symbol.6.free-refill-weight","generation.symbol.6.paid-initial-weight","generation.symbol.6.paid-refill-weight","generation.symbol.7.free-initial-weight","generation.symbol.7.free-refill-weight","generation.symbol.7.paid-initial-weight","generation.symbol.7.paid-refill-weight","generation.symbol.8.free-initial-weight","generation.symbol.8.free-refill-weight","generation.symbol.8.paid-initial-weight","generation.symbol.8.paid-refill-weight","generation.symbol.9.free-initial-weight","generation.symbol.9.free-refill-weight","generation.symbol.9.paid-initial-weight","generation.symbol.9.paid-refill-weight","generation.win-count","range.normal-max","range.normal-min","range.special-max","range.special-min","redis.connect-timeout-ms","redis.database","redis.game-id","redis.host","redis.password","redis.port","redis.socket-timeout-ms","redis.ssl","redis.username","retention.special-per-multiplier"));
        for(String key:p.stringPropertyNames())if(!allowed.contains(key))throw new IllegalArgumentException("未知或未支持的配置项: "+key);
        for(String key:new String[]{"redis.ssl","redis.clear-game-prefix","generation.clear-existing"})if(p.containsKey(key)&&!p.getProperty(key).trim().equalsIgnoreCase("true")&&!p.getProperty(key).trim().equalsIgnoreCase("false"))throw new IllegalArgumentException(key+" must be true or false");
        new LoaderLimits(p);
    }
    private static BigDecimal number(Properties p, String fallback, String... keys) {
        BigDecimal result = null;
        for (String key : keys) if (p.containsKey(key)) {
            BigDecimal value;
            try { value = new BigDecimal(p.getProperty(key).trim()); }
            catch (RuntimeException e) { throw new IllegalArgumentException("Invalid numeric configuration: " + key, e); }
            if (result != null && result.compareTo(value)!=0) throw new IllegalArgumentException("Conflicting configuration aliases: " + String.join(", ", keys));
            result = value;
        }
        return result == null ? new BigDecimal(fallback) : result;
    }
}
